    _UniffiHelpers.RustCall( (ref UniffiRustCallStatus _status) =>
    _UniFFILib.uniffi_tether_ffi_fn_method_transferprogress_advanced(thisPtr, FfiConverterUInt64.INSTANCE.Lower(@bytes), ref _status)
));
    }





