    string Host,
    ushort Port,
    string User,
    Secret[] Secrets
) : IDisposable {
    public void Dispose() {
    FFIObjectUtil.DisposeAll(
            this.Host,
            this.Port,
            this.User,
            this.Secrets);
    }
}

