/// grid; it can only do that from `columns / characters`, which is a whole
/// number of columns per character exactly when the run does not mix widths.
/// So a row breaks where the width changes, as well as where the style does.
/// </summary>
/// <param name="Columns">
/// How many columns the run covers. Not `text.count` — a wide character
/// is one grapheme over two columns, and a frontend laying out a
/// monospaced grid needs the column count to place the next run.
/// </param>
internal record StyledRun (
    string Text,
    /// <summary>
    /// How many columns the run covers. Not `text.count` — a wide character
    /// is one grapheme over two columns, and a frontend laying out a
    /// monospaced grid needs the column count to place the next run.
    /// </summary>
    uint Columns,
    CellStyle Style
) {
}

class FfiConverterTypeStyledRun: FfiConverterRustBuffer<StyledRun> {
    public static FfiConverterTypeStyledRun INSTANCE = new FfiConverterTypeStyledRun();

    public override StyledRun Read(BigEndianStream stream) {
        return new StyledRun(
            Text: FfiConverterString.INSTANCE.Read(stream),
            Columns: FfiConverterUInt32.INSTANCE.Read(stream),
            Style: FfiConverterTypeCellStyle.INSTANCE.Read(stream)
        );
    }

    public override int AllocationSize(StyledRun value) {
        return 0
            + FfiConverterString.INSTANCE.AllocationSize(value.Text)
            + FfiConverterUInt32.INSTANCE.AllocationSize(value.Columns)
            + FfiConverterTypeCellStyle.INSTANCE.AllocationSize(value.Style);
    }

    public override void Write(StyledRun value, BigEndianStream stream) {
            FfiConverterString.INSTANCE.Write(value.Text, stream);
            FfiConverterUInt32.INSTANCE.Write(value.Columns, stream);
            FfiConverterTypeCellStyle.INSTANCE.Write(value.Style, stream);
    }
}



