        switch (value) {
            case CaretShape.Block: stream.WriteInt(1); break;
            case CaretShape.Underline: stream.WriteInt(2); break;
            case CaretShape.Beam: stream.WriteInt(3); break;
            case CaretShape.Hidden: stream.WriteInt(4); break;
            default: throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeCaretShape.Write()", value));
        }
    }
}







internal record CellColor {

    public record Named (
        ColorName Name
    ) : CellColor {}

    public record Indexed (
        byte Index
    ) : CellColor {}

    public record Rgb (
        byte Red,
        byte Green,
        byte Blue
    ) : CellColor {}



}

class FfiConverterTypeCellColor : FfiConverterRustBuffer<CellColor>{
    public static FfiConverterRustBuffer<CellColor> INSTANCE = new FfiConverterTypeCellColor();

    public override CellColor Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new CellColor.Named(
                    FfiConverterTypeColorName.INSTANCE.Read(stream)
                );
            case 2:
                return new CellColor.Indexed(
                    FfiConverterUInt8.INSTANCE.Read(stream)
                );
            case 3:
                return new CellColor.Rgb(
                    FfiConverterUInt8.INSTANCE.Read(stream),
                    FfiConverterUInt8.INSTANCE.Read(stream),
                    FfiConverterUInt8.INSTANCE.Read(stream)
                );
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeCellColor.Read()", value));
        }
    }

    public override int AllocationSize(CellColor value) {
        switch (value) {
            case CellColor.Named variant_value:
                return 4
                    + FfiConverterTypeColorName.INSTANCE.AllocationSize(variant_value.Name);
            case CellColor.Indexed variant_value:
                return 4
                    + FfiConverterUInt8.INSTANCE.AllocationSize(variant_value.Index);
            case CellColor.Rgb variant_value:
                return 4
                    + FfiConverterUInt8.INSTANCE.AllocationSize(variant_value.Red)
                    + FfiConverterUInt8.INSTANCE.AllocationSize(variant_value.Green)
                    + FfiConverterUInt8.INSTANCE.AllocationSize(variant_value.Blue);
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeCellColor.AllocationSize()", value));
        }
    }

    public override void Write(CellColor value, BigEndianStream stream) {
        switch (value) {
            case CellColor.Named variant_value:
                stream.WriteInt(1);
                FfiConverterTypeColorName.INSTANCE.Write(variant_value.Name, stream);
                break;
            case CellColor.Indexed variant_value:
                stream.WriteInt(2);
                FfiConverterUInt8.INSTANCE.Write(variant_value.Index, stream);
                break;
            case CellColor.Rgb variant_value:
                stream.WriteInt(3);
                FfiConverterUInt8.INSTANCE.Write(variant_value.Red, stream);
                FfiConverterUInt8.INSTANCE.Write(variant_value.Green, stream);
                FfiConverterUInt8.INSTANCE.Write(variant_value.Blue, stream);
                break;
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeCellColor.Write()", value));
        }
    }
}







