/// <summary>
/// Why a file operation did not happen, in shapes a person can act on.
///
/// The server's status code is context inside `cause`, never a case of its
/// own (spec §18).
/// </summary>
internal class FileException: UniffiException {
    FileException() : base() {}
    FileException(String @Message) : base(@Message) {}

    // Each variant is a nested class


    public class NotFound : FileException {
        // Members
        public string @path;

        // Constructor
        public NotFound(
                string @path) : base(
                "@path" + "=" + @path) {

            this.@path = @path;
        }
    }


    public class Exists : FileException {
        // Members
        public string @path;

        // Constructor
        public Exists(
                string @path) : base(
                "@path" + "=" + @path) {

            this.@path = @path;
        }
    }


    public class PermissionDenied : FileException {
        // Members
        public string @path;

        // Constructor
        public PermissionDenied(
                string @path) : base(
                "@path" + "=" + @path) {

            this.@path = @path;
        }
    }


    public class NotEmpty : FileException {
        // Members
        public string @path;

        // Constructor
        public NotEmpty(
                string @path) : base(
                "@path" + "=" + @path) {

            this.@path = @path;
        }
    }

    public class Cancelled : FileException {
        public Cancelled() : base() {}
    }



    public class Disconnected : FileException {
        // Members
        public string @cause;

        // Constructor
        public Disconnected(
                string @cause) : base(
                "@cause" + "=" + @cause) {

            this.@cause = @cause;
        }
    }


    public class Failed : FileException {
        // Members
        public string @cause;

        // Constructor
        public Failed(
                string @cause) : base(
                "@cause" + "=" + @cause) {

            this.@cause = @cause;
        }
    }



}

class FfiConverterTypeFileError : FfiConverterRustBuffer<FileException>, CallStatusErrorHandler<FileException> {
    public static FfiConverterTypeFileError INSTANCE = new FfiConverterTypeFileError();

    public override FileException Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new FileException.NotFound(
                    FfiConverterString.INSTANCE.Read(stream));
            case 2:
                return new FileException.Exists(
                    FfiConverterString.INSTANCE.Read(stream));
            case 3:
                return new FileException.PermissionDenied(
                    FfiConverterString.INSTANCE.Read(stream));
            case 4:
                return new FileException.NotEmpty(
                    FfiConverterString.INSTANCE.Read(stream));
            case 5:
                return new FileException.Cancelled();
            case 6:
                return new FileException.Disconnected(
                    FfiConverterString.INSTANCE.Read(stream));
            case 7:
                return new FileException.Failed(
                    FfiConverterString.INSTANCE.Read(stream));
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeFileError.Read()", value));
        }
    }

    public override int AllocationSize(FileException value) {
        switch (value) {

            case FileException.NotFound variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@path);

            case FileException.Exists variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@path);

            case FileException.PermissionDenied variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@path);

            case FileException.NotEmpty variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@path);

            case FileException.Cancelled variant_value:
                return 4;

            case FileException.Disconnected variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@cause);

            case FileException.Failed variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@cause);
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeFileError.AllocationSize()", value));
        }
    }

    public override void Write(FileException value, BigEndianStream stream) {
        switch (value) {
            case FileException.NotFound variant_value:
                stream.WriteInt(1);
                FfiConverterString.INSTANCE.Write(variant_value.@path, stream);
                break;
            case FileException.Exists variant_value:
                stream.WriteInt(2);
                FfiConverterString.INSTANCE.Write(variant_value.@path, stream);
                break;
            case FileException.PermissionDenied variant_value:
                stream.WriteInt(3);
                FfiConverterString.INSTANCE.Write(variant_value.@path, stream);
                break;
            case FileException.NotEmpty variant_value:
                stream.WriteInt(4);
                FfiConverterString.INSTANCE.Write(variant_value.@path, stream);
                break;
            case FileException.Cancelled variant_value:
                stream.WriteInt(5);
                break;
            case FileException.Disconnected variant_value:
                stream.WriteInt(6);
                FfiConverterString.INSTANCE.Write(variant_value.@cause, stream);
                break;
            case FileException.Failed variant_value:
                stream.WriteInt(7);
                FfiConverterString.INSTANCE.Write(variant_value.@cause, stream);
                break;
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeFileError.Write()", value));
        }
    }
}





