/// <summary>
/// Errors are ours: a backend error number is diagnostic context, never the
/// public API (spec §18).
/// </summary>
internal class RenderFailure: UniffiException {
    RenderFailure() : base() {}
    RenderFailure(String @Message) : base(@Message) {}

    // Each variant is a nested class

    public class NoAdapter : RenderFailure {
        public NoAdapter() : base() {}
    }



    public class NoDevice : RenderFailure {
        // Members
        public string @cause;

        // Constructor
        public NoDevice(
                string @cause) : base(
                "@cause" + "=" + @cause) {

            this.@cause = @cause;
        }
    }


    public class Surface : RenderFailure {
        // Members
        public string @cause;

        // Constructor
        public Surface(
                string @cause) : base(
                "@cause" + "=" + @cause) {

            this.@cause = @cause;
        }
    }



}

class FfiConverterTypeRenderFailure : FfiConverterRustBuffer<RenderFailure>, CallStatusErrorHandler<RenderFailure> {
    public static FfiConverterTypeRenderFailure INSTANCE = new FfiConverterTypeRenderFailure();

    public override RenderFailure Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new RenderFailure.NoAdapter();
            case 2:
                return new RenderFailure.NoDevice(
                    FfiConverterString.INSTANCE.Read(stream));
            case 3:
                return new RenderFailure.Surface(
                    FfiConverterString.INSTANCE.Read(stream));
            default:
