/// <summary>
/// Everything that can go wrong, in our words.
///
/// A backend's error number is diagnostic context inside `cause`, never the
/// shape a consumer matches on — switching SSH libraries must not be a
/// breaking change for an application (spec §18).
/// </summary>
internal class TetherException: UniffiException {
    TetherException() : base() {}
    TetherException(String @Message) : base(@Message) {}

    // Each variant is a nested class

    public class Cancelled : TetherException {
        public Cancelled() : base() {}
    }



    public class TimedOut : TetherException {
        // Members
        public ulong @millis;

        // Constructor
        public TimedOut(
                ulong @millis) : base(
                "@millis" + "=" + @millis) {

            this.@millis = @millis;
        }
    }


    public class Unreachable : TetherException {
        // Members
        public string @endpoint;
        public string @cause;

        // Constructor
        public Unreachable(
                string @endpoint,
                string @cause) : base(
                "@endpoint" + "=" + @endpoint+ ", " +
                "@cause" + "=" + @cause) {

            this.@endpoint = @endpoint;

            this.@cause = @cause;
        }
    }

    /// <summary>
    /// The application's own trust decision, reported back to it. Not a
    /// failure of the connection: nothing was sent.
    /// </summary>

    public class HostRejected : TetherException {
        // Members
        public string @endpoint;

        // Constructor
        public HostRejected(
                string @endpoint) : base(
                "@endpoint" + "=" + @endpoint) {

            this.@endpoint = @endpoint;
        }
    }

    /// <summary>
    /// What the server would still accept, and the keys that were never
    /// offered to it — "your key was not used, and here is why" is often the
    /// whole story of a refused login. `remaining` is empty when nothing was
    /// refused by the server at all: every key given was unusable.
    /// </summary>

    public class AuthenticationFailed : TetherException {
        // Members
        public string[] @remaining;
        public SkippedKey[] @skipped;

        // Constructor
        public AuthenticationFailed(
                string[] @remaining,
                SkippedKey[] @skipped) : base(
                "@remaining" + "=" + @remaining+ ", " +
                "@skipped" + "=" + @skipped) {

            this.@remaining = @remaining;

            this.@skipped = @skipped;
        }
    }

    /// <summary>
    /// The credential was *accepted* and the server wants another factor, but
    /// none was left to offer. Distinct from a rejection, because telling
    /// someone their password was wrong when it was right is its own failure.
    /// </summary>

    public class MoreFactorsNeeded : TetherException {
        // Members
        public string[] @remaining;

        // Constructor
        public MoreFactorsNeeded(
                string[] @remaining) : base(
                "@remaining" + "=" + @remaining) {

            this.@remaining = @remaining;
        }
    }

    public class NothingToOffer : TetherException {
        public NothingToOffer() : base() {}
    }


    /// <summary>
    /// Neither side would give us a shell. Worded for both, because by this
    /// point a consumer holds a session and does not care whether the shell
    /// it asked for was going to run here or somewhere else.
    /// </summary>

    public class ShellRefused : TetherException {
        // Members
        public string @cause;

        // Constructor
        public ShellRefused(
                string @cause) : base(
                "@cause" + "=" + @cause) {

            this.@cause = @cause;
        }
    }

    /// <summary>
    /// The system does not let an application do this at all.
    ///
    /// iOS and a local shell is the case it exists for: there is no
    /// `fork`/`exec` outside the sandbox. Distinct from a refusal, because a
    /// refusal is something a person might fix and this is not.
    /// </summary>

    public class Unsupported : TetherException {
        // Members
        public string @what;

        // Constructor
        public Unsupported(
                string @what) : base(
                "@what" + "=" + @what) {

            this.@what = @what;
        }
    }


    public class Disconnected : TetherException {
        // Members
        public string @cause;

        // Constructor
        public Disconnected(
                string @cause) : base(
                "@cause" + "=" + @cause) {

            this.@cause = @cause;
        }
    }

    public class SessionEnded : TetherException {
        public SessionEnded() : base() {}
    }



    public class Protocol : TetherException {
        // Members
        public string @cause;

        // Constructor
        public Protocol(
                string @cause) : base(
                "@cause" + "=" + @cause) {

            this.@cause = @cause;
        }
    }



}

class FfiConverterTypeTetherError : FfiConverterRustBuffer<TetherException>, CallStatusErrorHandler<TetherException> {
    public static FfiConverterTypeTetherError INSTANCE = new FfiConverterTypeTetherError();

    public override TetherException Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new TetherException.Cancelled();
            case 2:
                return new TetherException.TimedOut(
                    FfiConverterUInt64.INSTANCE.Read(stream));
            case 3:
                return new TetherException.Unreachable(
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream));
            case 4:
                return new TetherException.HostRejected(
                    FfiConverterString.INSTANCE.Read(stream));
            case 5:
                return new TetherException.AuthenticationFailed(
                    FfiConverterSequenceString.INSTANCE.Read(stream),
                    FfiConverterSequenceTypeSkippedKey.INSTANCE.Read(stream));
            case 6:
                return new TetherException.MoreFactorsNeeded(
                    FfiConverterSequenceString.INSTANCE.Read(stream));
            case 7:
                return new TetherException.NothingToOffer();
            case 8:
                return new TetherException.ShellRefused(
                    FfiConverterString.INSTANCE.Read(stream));
            case 9:
                return new TetherException.Unsupported(
                    FfiConverterString.INSTANCE.Read(stream));
            case 10:
                return new TetherException.Disconnected(
                    FfiConverterString.INSTANCE.Read(stream));
            case 11:
                return new TetherException.SessionEnded();
            case 12:
                return new TetherException.Protocol(
                    FfiConverterString.INSTANCE.Read(stream));
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeTetherError.Read()", value));
        }
    }

    public override int AllocationSize(TetherException value) {
        switch (value) {

            case TetherException.Cancelled variant_value:
                return 4;

            case TetherException.TimedOut variant_value:
                return 4
                    + FfiConverterUInt64.INSTANCE.AllocationSize(variant_value.@millis);

            case TetherException.Unreachable variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@endpoint)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@cause);

            case TetherException.HostRejected variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@endpoint);

            case TetherException.AuthenticationFailed variant_value:
                return 4
                    + FfiConverterSequenceString.INSTANCE.AllocationSize(variant_value.@remaining)
                    + FfiConverterSequenceTypeSkippedKey.INSTANCE.AllocationSize(variant_value.@skipped);

            case TetherException.MoreFactorsNeeded variant_value:
                return 4
                    + FfiConverterSequenceString.INSTANCE.AllocationSize(variant_value.@remaining);

            case TetherException.NothingToOffer variant_value:
                return 4;

            case TetherException.ShellRefused variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@cause);

            case TetherException.Unsupported variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@what);

            case TetherException.Disconnected variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@cause);

            case TetherException.SessionEnded variant_value:
                return 4;

            case TetherException.Protocol variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@cause);
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeTetherError.AllocationSize()", value));
        }
    }

    public override void Write(TetherException value, BigEndianStream stream) {
        switch (value) {
            case TetherException.Cancelled variant_value:
                stream.WriteInt(1);
                break;
            case TetherException.TimedOut variant_value:
                stream.WriteInt(2);
                FfiConverterUInt64.INSTANCE.Write(variant_value.@millis, stream);
                break;
            case TetherException.Unreachable variant_value:
                stream.WriteInt(3);
                FfiConverterString.INSTANCE.Write(variant_value.@endpoint, stream);
                FfiConverterString.INSTANCE.Write(variant_value.@cause, stream);
                break;
            case TetherException.HostRejected variant_value:
                stream.WriteInt(4);
                FfiConverterString.INSTANCE.Write(variant_value.@endpoint, stream);
                break;
            case TetherException.AuthenticationFailed variant_value:
                stream.WriteInt(5);
                FfiConverterSequenceString.INSTANCE.Write(variant_value.@remaining, stream);
                FfiConverterSequenceTypeSkippedKey.INSTANCE.Write(variant_value.@skipped, stream);
                break;
            case TetherException.MoreFactorsNeeded variant_value:
                stream.WriteInt(6);
                FfiConverterSequenceString.INSTANCE.Write(variant_value.@remaining, stream);
                break;
            case TetherException.NothingToOffer variant_value:
                stream.WriteInt(7);
                break;
            case TetherException.ShellRefused variant_value:
                stream.WriteInt(8);
                FfiConverterString.INSTANCE.Write(variant_value.@cause, stream);
                break;
            case TetherException.Unsupported variant_value:
                stream.WriteInt(9);
                FfiConverterString.INSTANCE.Write(variant_value.@what, stream);
                break;
            case TetherException.Disconnected variant_value:
                stream.WriteInt(10);
                FfiConverterString.INSTANCE.Write(variant_value.@cause, stream);
                break;
            case TetherException.SessionEnded variant_value:
                stream.WriteInt(11);
                break;
            case TetherException.Protocol variant_value:
                stream.WriteInt(12);
                FfiConverterString.INSTANCE.Write(variant_value.@cause, stream);
                break;
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeTetherError.Write()", value));
        }
    }
}





